package com.cgengine.render_engine;
import com.cgengine.math.*;
/** View/projection helpers use row-major matrices, column vectors and M × v. */
public final class GraphicConveyor {
 private GraphicConveyor(){} public static Matrix4f rotateScaleTranslate(){return Matrix4f.identity();} public static Matrix4f lookAt(Vector3f eye,Vector3f target){return lookAt(eye,target,new Vector3f(0,1,0));}
 public static Matrix4f lookAt(Vector3f eye,Vector3f target,Vector3f up){if(eye==null||target==null||up==null)throw new IllegalArgumentException("lookAt arguments are null");Vector3f forward=VectorMath.subtract(target,eye);if(VectorMath.length(forward)==0)throw new IllegalArgumentException("Camera eye and target must differ");forward=VectorMath.normalize(forward);Vector3f right=VectorMath.cross(up,forward);if(VectorMath.length(right)==0)throw new IllegalArgumentException("Camera up vector is parallel to view direction");right=VectorMath.normalize(right);Vector3f correctedUp=VectorMath.normalize(VectorMath.cross(forward,right));return new Matrix4f(right.x(),right.y(),right.z(),-VectorMath.dot(right,eye),correctedUp.x(),correctedUp.y(),correctedUp.z(),-VectorMath.dot(correctedUp,eye),forward.x(),forward.y(),forward.z(),-VectorMath.dot(forward,eye),0,0,0,1);}
 /** Matches the transposed reference matrix from GraphicConveyorTest. */ public static Matrix4f perspective(float fov,float aspect,float near,float far){if(!Float.isFinite(fov)||!Float.isFinite(aspect)||fov<=0||aspect<=0||near<=0||far<=near)throw new IllegalArgumentException("Invalid perspective parameters");float f=(float)(1/Math.tan(fov*.5));return new Matrix4f(f/aspect,0,0,0,0,f,0,0,0,0,(far+near)/(far-near),2*near*far/(near-far),0,0,1,0);}
 public static Vector3f multiplyMatrix4ByVector3(Matrix4f matrix,Vector3f vertex){return MatrixMath.perspectiveDivide(MatrixMath.multiply(matrix,new Vector4f(vertex.x(),vertex.y(),vertex.z(),1)));} public static Vector2f vertexToVec2(Vector3f vertex,int width,int height){if(width<=0||height<=0)throw new IllegalArgumentException("Viewport dimensions must be positive");return new Vector2f(vertex.x()*width+width/2f,-vertex.y()*height+height/2f);}
}
